function openMap(selectId=game.state.systemId,tab='galaxy'){dialog.open(tab==='local'?'Local chart':'The known sky','map',{eyebrow:'NAVIGATION / '+game.galaxy.length+' STAR SYSTEMS',wide:true});const tabs=document.createElement('div');tabs.className='panel-tabs';for(const [key,label]of [['galaxy','Galaxy'],['local',game.state.mode==='person'?'This place':'Local system']]){const b=document.createElement('button');b.className=tab===key?'active':'';b.textContent=label;b.onclick=()=>openMap(selectId,key);tabs.append(b);}dialog.body.append(tabs);if(tab==='local'){openLocalMapContent();return;}
 dialog.body.insertAdjacentHTML('beforeend','<input class="map-search" id="mapSearch" placeholder="Find a star system…" aria-label="Find a star system"><div class="galaxy-layout"><div><div class="galaxy-canvas-wrap"><canvas id="galaxyCanvas" aria-label="Interactive galaxy chart. Tap a star to inspect, drag to pan."></canvas><div class="map-scale">DRAG TO PAN · SELECT A STAR</div><div class="map-toolbar"><button id="zoomOut" aria-label="Zoom out">−</button><button id="mapHome">HOME</button><button id="zoomIn" aria-label="Zoom in">+</button></div></div><div class="map-legend" id="mapLegend"></div></div><div class="system-info" id="systemInfo"></div></div><div id="nearbyStars" class="system-nearby"></div>');const gc=$('galaxyCanvas'),g=gc.getContext('2d'),home=game.currentSystem;let selected=game.galaxy.find(s=>s.id===selectId)??home,center={x:home.gx,y:home.gy},scale=9,pan=null;const known=new Set(game.state.visited);
 $('mapLegend').innerHTML=FACTIONS.map(f=>`<span><i style="background:${f.color}"></i>${esc(f.short)}</span>`).join('');
 const size=()=>{const r=gc.getBoundingClientRect();gc.width=Math.round(r.width*(window.devicePixelRatio>1?1.5:1));gc.height=Math.round(r.height*(window.devicePixelRatio>1?1.5:1));return{w:r.width,h:r.height,ratio:gc.width/r.width};};
 const draw=()=>{if(!gc.isConnected)return;const{w,h,ratio}=size();g.setTransform(ratio,0,0,ratio,0,0);g.fillStyle='#07131e';g.fillRect(0,0,w,h);const to=s=>({x:w/2+(s.gx-center.x)*scale,y:h/2+(s.gy-center.y)*scale});const rr=seededRandom(846);for(let i=0;i<200;i++){g.fillStyle=i%5?'#273e50':'#576d79';g.fillRect(rr()*w,rr()*h,1,1);}g.strokeStyle='#24435355';g.lineWidth=.5;for(let i=-50;i<=50;i+=5){let x=w/2+(i-center.x)*scale,y=h/2+(i-center.y)*scale;g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.moveTo(0,y);g.lineTo(w,y);g.stroke();}
 const hp=to(home);if(game.state.ship.warpRange>0){g.fillStyle='#67aa8b0c';g.strokeStyle='#6aaf9488';g.setLineDash([3,5]);g.beginPath();g.arc(hp.x,hp.y,game.state.ship.warpRange*scale,0,Math.PI*2);g.fill();g.stroke();g.setLineDash([]);}const nearby=game.galaxy.filter(s=>Math.hypot(s.gx-home.gx,s.gy-home.gy)<Math.max(5,game.state.ship.warpRange));g.strokeStyle='#6a9f8240';for(const s of nearby){const p=to(s);g.beginPath();g.moveTo(hp.x,hp.y);g.lineTo(p.x,p.y);g.stroke();}
 for(const s of game.galaxy){const p=to(s);if(p.x<-10||p.x>w+10||p.y<-10||p.y>h+10)continue;const f=FACTIONS.find(f=>f.id===s.faction),isSelected=s.id===selected.id,isCurrent=s.id===home.id;g.fillStyle=f?.color??'#aac5b4';g.globalAlpha=s.authored||known.has(s.id)?1:.55;const radius=isCurrent?4:s.authored?3:2;g.fillRect(Math.round(p.x)-radius/2,Math.round(p.y)-radius/2,radius,radius);g.globalAlpha=1;if(isSelected){g.strokeStyle='#eed9a3';g.strokeRect(p.x-7,p.y-7,14,14);}if(isCurrent){g.strokeStyle='#a8c8bd';g.beginPath();g.arc(p.x,p.y,10,0,Math.PI*2);g.stroke();}if((s.authored&&scale>7)||isSelected||isCurrent){g.font='9px "Courier New",monospace';g.fillStyle=isSelected?'#eddaa6':s.authored?'#adc0c6':'#78939e';g.textAlign='left';g.fillText(s.name,p.x+10,p.y+3);}}
 if(selected.id!==home.id){const p=to(selected);g.strokeStyle='#e1c58c99';g.setLineDash([2,5]);g.beginPath();g.moveTo(hp.x,hp.y);g.lineTo(p.x,p.y);g.stroke();g.setLineDash([]);}};
 const info=()=>{const f=FACTIONS.find(f=>f.id===selected.faction),travel=game.travelInfo(selected.id),dist=Math.hypot(selected.gx-home.gx,selected.gy-home.gy);$('systemInfo').innerHTML=`<span class="eyebrow" style="color:${f?.color}">${esc(f?.name??'FRONTIER SPACE')}</span><h3>${esc(selected.name)}</h3><p>${esc(selected.description)}</p><div class="system-facts"><span>${dist.toFixed(1)} light-years away</span><span>Threat ${'◆'.repeat(selected.danger)}${'◇'.repeat(5-selected.danger)}</span><span>${selected.bodies.length} charted destinations</span><span>${known.has(selected.id)?'VISITED':'UNVISITED'}</span><span>Your range: ${game.state.ship.warpRange} ly</span><span>${travel.fuelCost??0} fuel to jump</span></div><button id="jumpButton" class="jump-button" ${travel.ok?'':'disabled'}>${travel.ok?'Engage fold drive →':selected.id===home.id?'Current system':game.hasHyperdrive?'Jump unavailable':'Fold drive not installed'}</button><p class="mini muted">${esc(travel.ok?'Land at a port to refuel, find work, and meet the people who live here.':travel.reason)}</p>`;$('jumpButton').onclick=()=>{if(result(game.travel(selected.id))){dialog.close();surface=null;surfaceKey='';tracked=game.system.bodies.find(b=>b.kind==='station')?.id??game.system.bodies[0]?.id;transitionFlash=1;renderer.lastSystem=null;audio.play('jump');processEvents();saveNow();setTimeout(()=>{if(!dialog.opened){const arrival=game.availableEncounters().find(e=>e.id==='earth_arrival');if(arrival){const r=game.triggerEncounter(arrival.id);if(r.ok)openEncounter(r.encounter);}}},150);}};draw();};
 const local=game.galaxy.filter(s=>s.id!==home.id).sort((a,b)=>Math.hypot(a.gx-home.gx,a.gy-home.gy)-Math.hypot(b.gx-home.gx,b.gy-home.gy)).slice(0,7);$('nearbyStars').innerHTML='<span class="mini muted" style="padding:7px 0">NEARBY</span>';for(const s of local){const b=document.createElement('button');b.textContent=s.name;b.onclick=()=>{selected=s;info();};$('nearbyStars').append(b);}
 gc.addEventListener('pointerdown',e=>{e.preventDefault();gc.setPointerCapture(e.pointerId);pan={id:e.pointerId,x:e.clientX,y:e.clientY,cx:center.x,cy:center.y,moved:false};});gc.addEventListener('pointermove',e=>{if(!pan||pan.id!==e.pointerId)return;const dx=e.clientX-pan.x,dy=e.clientY-pan.y;if(Math.hypot(dx,dy)>5)pan.moved=true;center={x:pan.cx-dx/scale,y:pan.cy-dy/scale};draw();});gc.addEventListener('pointerup',e=>{if(!pan||pan.id!==e.pointerId)return;if(!pan.moved){const r=gc.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/scale+center.x,y=(e.clientY-r.top-r.height/2)/scale+center.y;const nearest=game.galaxy.map(s=>({s,d:Math.hypot(s.gx-x,s.gy-y)*scale})).sort((a,b)=>a.d-b.d)[0];if(nearest?.d<22){selected=nearest.s;info();}}pan=null;});gc.addEventListener('pointercancel',()=>pan=null);gc.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(3.4,Math.min(25,scale*(e.deltaY<0?1.15:.87)));draw();},{passive:false});$('zoomIn').onclick=()=>{scale=Math.min(25,scale*1.3);draw();};$('zoomOut').onclick=()=>{scale=Math.max(3.4,scale/1.3);draw();};$('mapHome').onclick=()=>{center={x:home.gx,y:home.gy};selected=home;scale=9;info();};$('mapSearch').addEventListener('input',e=>{const query=e.target.value.trim().toLowerCase();if(query.length<2)return;const found=game.galaxy.find(s=>s.name.toLowerCase()===query)??game.galaxy.find(s=>s.name.toLowerCase().includes(query));if(found){selected=found;center={x:found.gx,y:found.gy};info();}});requestAnimationFrame(()=>info());
}
function openLocalMapContent(){if(game.state.mode==='person'&&surface){dialog.body.insertAdjacentHTML('beforeend',`<p class="section-note">${esc(surface.name)} · Choose a destination to mark it while you walk.</p><div class="galaxy-canvas-wrap" style="min-height:220px"><canvas id="localSurfaceCanvas" style="height:min(48vh,460px);object-fit:contain" aria-label="Local walking map"></canvas></div><div class="system-nearby" id="localPlaces"></div>`);const c=$('localSurfaceCanvas');c.width=surface.width;c.height=surface.height;drawSurface(c.getContext('2d'),surface,{person:game.state.person,width:c.width,height:c.height,cameraX:0,cameraY:0,time:elapsed,flags:game.state.flags,mission:{targetEntityId:surfaceTarget}});for(const e of surface.entities.filter(e=>['exit','mechanic','jobboard','work','sample','crate','delivery','terminal'].includes(e.type)&&!e.hidden)){const b=document.createElement('button');b.textContent=e.name;b.onclick=()=>{surfaceTarget=e.id;dialog.close();toast(`${e.name} marked. Follow the gold direction marker.`);};$('localPlaces').append(b);}}else{dialog.body.insertAdjacentHTML('beforeend','<p class="section-note">Select a contact to mark it in ship mode. Fly close enough to dock, land, scan, or mine.</p>');for(const b of [...game.system.bodies,...game.system.signals.filter(s=>!s.resolved)]){const card=document.createElement('div');card.className='entry-card';card.innerHTML=`<div class="entry-top"><span class="entry-title">${esc(b.name)}</span><span class="entry-meta">${Math.round(distance(b,game.state.ship))} m</span></div><p>${esc(b.lore??b.kind)}</p><button>Track contact</button>`;card.querySelector('button').onclick=()=>{tracked=b.id;dialog.close();};dialog.body.append(card);}const b=document.createElement('button');b.className='button-secondary';b.textContent='Track nearby mining belt';b.onclick=()=>{tracked=game.system.asteroids.filter(a=>a.hp>0).sort((a,b)=>distance(a,game.state.ship)-distance(b,game.state.ship))[0]?.id;dialog.close();};dialog.body.append(b);}}
function openSettings(){dialog.open('A moment between stars','settings',{eyebrow:'PAUSED / VOYAGE SAVED'});saveNow();const form=document.createElement('div');const defs=[['guidance','Guidance','Simple keeps useful directions visible. Expert leaves more discovery to you.','select',[['simple','Simple'],['moderate','Moderate'],['expert','Expert']]],['controlScale','Touch control size','Adjust the space beneath each thumb.','range',[.8,1.2,.05]],['textScale','Interface text size','Increase the size of menus and labels.','range',[1,1.2,.05]],['flightAssist','Flight assist','Release the stick to slow down. Switch off for more drift.','checkbox'],['leftHanded','Swap thumb controls','Move the joystick to your right hand.','checkbox'],['sound','Sound effects','Engine pulses, footsteps, mining, and ship systems.','checkbox'],['music','Ambient score','A quiet, original electronic soundscape.','checkbox'],['reduceMotion','Reduce motion','Steadier camera and fewer atmospheric changes.','checkbox']];
 for(const[key,label,help,type,options]of defs){const row=document.createElement('div');row.className='setting-row';const text=document.createElement('label');text.htmlFor='setting-'+key;text.innerHTML=`<strong>${esc(label)}</strong><small>${esc(help)}</small>`;let input;if(type==='select'){input=document.createElement('select');for(const[value,name]of options){const o=document.createElement('option');o.value=value;o.textContent=name;o.selected=settings[key]===value;input.append(o);}}else{input=document.createElement('input');input.type=type;if(type==='range'){[input.min,input.max,input.step]=options;input.value=settings[key];}else input.checked=!!settings[key];}input.id='setting-'+key;input.addEventListener(type==='range'?'input':'change',()=>{settings[key]=type==='checkbox'?input.checked:type==='range'?Number(input.value):input.value;applySettings(settings);audio.mute();resize();updateHUD();});row.append(text,input);form.append(row);}dialog.body.append(form);const buttons=document.createElement('div');buttons.className='setting-buttons';for(const[label,fn]of [['Resume voyage',()=>dialog.close()],['Controls & help',openHelp],['Export / import save',openSavePanel],['Return to title',()=>{dialog.close();saveNow();playing=false;$('welcome').hidden=false;$('continueButton').hidden=false;document.body.classList.add('welcome-active');}]]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;buttons.append(b);}dialog.body.append(buttons);dialog.body.insertAdjacentHTML('beforeend','<p class="audio-note">Progress is saved in this browser. Export a save to move your voyage to another device. Menus pause the simulation.</p>');}
function openSavePanel(){dialog.open('Carry your voyage with you','save',{eyebrow:'LOCAL SAVE / EXPORT & IMPORT'});dialog.html('<p>Your save contains your ship, contracts, decisions, and changes to visited systems. Download a copy, or paste a previously exported save below.</p><div class="dialogue-actions"><button id="downloadSave" class="button-primary">Download save</button></div><h3>Import a voyage</h3><textarea id="saveText" aria-label="Paste Farwake save" placeholder="Paste your Farwake save JSON here…"></textarea><div class="dialogue-actions"><button id="importSave">Check and import save</button></div><div id="saveFeedback" class="mini muted" style="margin-top:12px"></div>');$('downloadSave').onclick=()=>{const blob=new Blob([game.serialize()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='farwake-voyage.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('importSave').onclick=()=>{try{const raw=JSON.parse($('saveText').value);if(!raw||typeof raw!=='object'||!raw.seed||!raw.ship||!raw.stats||!Array.isArray(raw.flags))throw new Error('This does not look like a Farwake save.');const next=Game.fromSave(raw);game=next;surface=null;surfaceKey='';ensureSurface(false);saveNow();dialog.close();toast('Voyage imported. Welcome back, captain.','good');updateHUD();}catch(e){$('saveFeedback').textContent='Could not import: '+e.message;}};}
function openHelp(){dialog.open('The captain’s field guide','help',{eyebrow:'SHIP MODE + PERSON MODE'});dialog.html('<h3>Your first steps</h3><p>Dock at Kettle Station. Walk to the contract exchange for a maintenance shift, find Iona in the workshop, and explore the station. Launch into Hearth to mine ore and investigate signals. Earn vector thrusters, an echo scanner, and finally a fold drive to reach the other stars.</p><h3>Two modes, one voyage</h3><p><strong>Ship mode:</strong> steer toward a destination, hold FIRE to shoot ahead, hold MINE near asteroids, and BOOST when you need space. Approach planets, moons, and stations until the docking or landing prompt appears.<br><strong>Person mode:</strong> walk up to someone or something and use TALK / USE. Visit rooms, accept contracts, carry freight, repair relays, collect field samples, and make decisions. Return through the airlock or landing shuttle to take the helm.</p><h3>Desktop controls</h3><table class="keyboard-table"><tbody><tr><td>WASD / arrow keys</td><td>Steer or walk</td></tr><tr><td>E</td><td>Dock, land, talk, or use</td></tr><tr><td>Space</td><td>Fire / interact on foot</td></tr><tr><td>R</td><td>Mine nearby asteroids</td></tr><tr><td>Shift</td><td>Boost / run</td></tr><tr><td>X</td><td>Brake</td></tr><tr><td>F</td><td>Scan nearby signal</td></tr><tr><td>M / J / I</td><td>Map / journal / ship</td></tr><tr><td>C</td><td>Enter your ship’s cabin</td></tr><tr><td>Esc / P</td><td>Pause or close a menu</td></tr></tbody></table><h3>Touch controls</h3><p>Left thumb moves; the right cluster fires, mines, and boosts. On foot, the large button interacts. The context strip also works for docking and conversations. Controls stay independent when used together. Size, handedness, sound, and guidance are in Pause.</p><h3>A few useful things to know</h3><p>Your mining beam automatically locks onto the closest rock in range. Shields recharge after you avoid damage. Fuel is spent on fold jumps; local flight will not strand you. A destroyed ship is recovered with a salvage penalty. Ports offer emergency fuel if you cannot afford to leave. Contracts pay at their stated destination.</p><p class="mini muted">Farwake v0.1 · A single-player DailyFlyer game. Authored story, seeded systems, and persistent choices. Your save stays in this browser unless you export it.</p>');}
function updateHUD(){const s=game.state,sh=s.ship,onFoot=s.mode==='person',body=game.currentBody,sys=game.currentSystem,f=FACTIONS.find(f=>f.id===(body?.faction??sys.faction));$('credits').textContent=fmt(s.credits);$('cargo').textContent=`${game.cargoUsed} / ${sh.cargoCap}`;$('fuel').textContent=Math.round(sh.fuel/sh.maxFuel*100);$('modePill').querySelector('span').textContent=onFoot?'PERSON MODE':'SHIP MODE';$('shipName').textContent=onFoot?'CINDER / DOCKED':'CINDER / SPARROW CLASS';$('locationName').textContent=onFoot?(body?.name??surface?.name):sys.name;$('sectorLabel').textContent=onFoot?sys.name.toUpperCase()+' SYSTEM / '+(surface?.kind==='ship'?'CREW DECK':'ON FOOT'):'THE CINDER REACH / '+(sys.authored?'CHARTED SYSTEM':'FRONTIER');$('locationDetail').textContent=(f?.short??'INDEPENDENT')+' SPACE · '+(onFoot?'LOCAL EXPLORATION':game.hasHyperdrive?'FOLD DRIVE ONLINE':'SUBLIGHT FLIGHT');$('coordinate').textContent=onFoot?`${Math.round(s.person.x)} / ${Math.round(s.person.y)}`:`${Math.round(sh.x).toString().padStart(4,'0')} / ${Math.round(sh.y).toString().padStart(4,'0')}`;$('contactsPanel').style.display=onFoot?'none':'';
 const meters=[['hull',sh.hull,sh.maxHull],['shield',sh.shield,sh.maxShield],['energy',sh.energy,sh.maxEnergy]];for(const[id,value,max]of meters){$(id+'Number').textContent=Math.ceil(value);$(id+'Meter').style.width=Math.max(0,Math.min(100,value/max*100))+'%';}$('speedLabel').innerHTML=onFoot?`<small>VITALITY</small> ${Math.ceil(s.person.health)}`:`${Math.round(Math.hypot(sh.vx,sh.vy)).toString().padStart(3,'0')} <small>m/s</small>`;
 const chapter=game.chapter,job=s.missions.find(m=>m.status!=='completed'&&m.type==='work'&&m.targetBody===s.locationId);$('objectiveKind').textContent=job?'LOCAL CONTRACT':chapter?'THE QUIET EARTH':'YOUR OWN WAY';$('objectiveTitle').textContent=job?job.title+` · ${job.progress}/${job.goal}`:chapter?.title??'The galaxy is still open';let hint=job?(job.status==='ready'?'Return to the contract exchange for payment.':'Calibrate the amber maintenance relays around this place.'):chapter?.objective??'Explore, trade, and choose where you go next.';if(!onFoot&&!s.completedChapters.length)hint='Dock at Kettle Station. Meet Iona, then find the contract exchange.';if(onFoot&&s.locationId==='kettle'&&!s.flags.includes('accepted_job')&&!s.completedChapters.length)hint='Find the contract exchange in the central concourse. Iona’s workshop is to the north.';if(onFoot&&surface?.kind==='ship')hint='Walk your crew deck. Use the helm to return to ship mode; MAP can mark the way.';$('objectiveText').textContent=settings.guidance==='expert'?'Your journal keeps the details.':hint;$('objectiveText').style.display=settings.guidance==='expert'?'none':'';
 const n=nearby();let context=onFoot?'Walk close to a person or workstation':'Fly toward a port, signal, or asteroid belt';if(n){if(onFoot)context=n.type==='exit'?(surface?.kind==='ship'?'Take the helm':'Return to Cinder'):n.type==='npc'||n.type==='crew'?'Talk to '+n.name:n.type==='mechanic'?'Visit '+n.name:n.type==='jobboard'?'Open the contract exchange':n.type==='work'?'Calibrate '+n.name:n.type==='crate'?'Pick up freight crate':n.type==='delivery'?'Use loading pad':n.type==='sample'?'Collect '+n.name:'Use '+n.name;else context=n.type==='dock'?(n.body.kind==='station'?'Dock at ':'Land on ')+n.name:n.type==='signal'?'Investigate '+n.name:n.type==='salvage'?'Collect salvage':'Hail '+n.name;}$('contextText').textContent=context;$('contextButton').classList.toggle('idle',!n);$('fireButton').querySelector('small').textContent=onFoot?'USE':'FIRE';$('fireButton').querySelector('span').textContent=onFoot?'◇':'✛';$('mineButton').querySelector('small').textContent=onFoot?'LOG':'MINE';$('boostButton').querySelector('small').textContent=onFoot?'RUN':'BOOST';$('footerTime').textContent='YEAR 2481 · '+String(Math.floor(s.stats.time/60)).padStart(2,'0')+':'+String(Math.floor(s.stats.time)%60).padStart(2,'0');
 if(!onFoot){const contacts=[...game.system.bodies];const sig=game.system.signals.filter(x=>!x.resolved).sort((a,b)=>distance(a,sh)-distance(b,sh))[0];if(sig)contacts.push(sig);const rock=game.system.asteroids.filter(x=>x.hp>0).sort((a,b)=>distance(a,sh)-distance(b,sh))[0];if(rock)contacts.push({...rock,name:'Mining belt',kind:'ore'});const list=$('contactsList');list.replaceChildren();for(const b of contacts.slice(0,5)){const button=document.createElement('button');button.className='contact-row'+(tracked===b.id?' selected':'');button.innerHTML=`<span class="contact-symbol">${b.kind==='station'?'⊞':b.kind==='planet'?'◉':b.kind==='moon'?'◌':b.kind==='ore'?'◇':'⌁'}</span><span>${esc(b.name)}<small>${esc(b.kind?.toUpperCase()??'CONTACT')}</small></span><span class="dist">${Math.round(distance(b,sh))}m</span>`;button.onclick=()=>{tracked=b.id;updateHUD();};list.append(button);}}
}
function processEvents(){for(const e of game.drainEvents()){if(e.type==='shot'){audio.play('fire');continue;}if(e.type==='hit'||e.type==='damage'){audio.play('hit');continue;}if(e.type==='mined'){if(game.system.asteroids.some(a=>a.id===tracked&&a.hp<=0))tracked=game.system.asteroids.filter(a=>a.hp>0).sort((a,b)=>distance(a,game.state.ship)-distance(b,game.state.ship))[0]?.id;audio.play('mine');toast(e.text,'good',1800);continue;}if(e.type==='encounter'){if(!dialog.opened&&playing)openEncounter(e.encounter??game.getEncounter());continue;}if(e.type==='chapter'){audio.play('quest');toast(e.chapter.title+' complete. Your journal has the next chapter.','good',6000);continue;}if(e.type==='job-complete'||e.type==='upgrade')audio.play('quest');if(e.type==='salvage')audio.play('pickup');if(e.type==='rescue')audio.play('alert');if(e.type==='choice')continue;if(e.text)toast(e.text,['rescue'].includes(e.type)?'bad':['job-complete','upgrade','service','salvage'].includes(e.type)?'good':'info');}}
function resize(){const r=canvas.getBoundingClientRect(),scale=window.matchMedia('(pointer:coarse)').matches?1.35:1.5;canvas.width=Math.max(240,Math.round(r.width/scale));canvas.height=Math.max(160,Math.round(r.height/scale));ctx.imageSmoothingEnabled=false;controls?.clear();}
new ResizeObserver(resize).observe($('flightdeck'));window.addEventListener('orientationchange',()=>{controls.clear();setTimeout(resize,150);});resize();
const attract={state:{systemId:'attract',ship:{x:0,y:30,vx:20,vy:0,angle:-.42,shield:35},jumpFlash:0},system:{bodies:[{id:'welcome-planet',name:'Morrow',kind:'planet',x:300,y:-110,radius:170,biome:'temperate'},{id:'welcome-moon',name:'Tinbell',kind:'moon',x:570,y:85,radius:47,biome:'barren'},{id:'welcome-port',name:'Kettle',kind:'station',x:35,y:210,radius:50,biome:'station'}],asteroids:Array.from({length:18},(_,i)=>({id:'attract-'+i,x:220+i*23,y:170+Math.sin(i*.8)*57,radius:7+i%8,hp:10,seed:i+8})),enemies:[],traffic:[{x:80,y:145,angle:-.6,vx:10}],signals:[],bullets:[],pickups:[]}};
let wasFire=false,wasMine=false;
function frame(now){const rawDt=Math.max(0,(now-(lastTime||now))/1000);const dt=Math.min(.15,rawDt);lastTime=now;elapsed+=dt;
 if(playing&&!dialog.opened&&!document.hidden){const input=controls.vector();input.flightAssist=settings.flightAssist;stepAccumulator+=dt;let count=0;while(stepAccumulator>=1/60&&count<10){game.step(1/60,input);if(game.state.mode==='person'){ensureSurface();game.state.person.speed=input.boost?155:112;if(surface)movePerson(surface,game.state.person,input.x,input.y,1/60);}stepAccumulator-=1/60;count++;}if(game.state.mode==='person'){if(input.fire&&!wasFire&&!dialog.opened)interact();if(input.mine&&!wasMine&&!dialog.opened)openJournal('missions');if(game.state.person.moving)audio.play('footstep');}wasFire=input.fire;wasMine=input.mine;processEvents();if(!dialog.opened&&game.state.pendingEncounter)openEncounter(game.getEncounter());saveTimer+=dt;if(saveTimer>12){saveNow();saveTimer=0;}audio.atmosphere(game.state.stats.time,game.state.mode,settings.music);
 }else{stepAccumulator=0;wasFire=false;wasMine=false;}
 const w=canvas.width,h=canvas.height;if(playing&&game.state.mode==='person'){ensureSurface();if(surface){const camera=drawSurface(ctx,surface,{person:game.state.person,width:w,height:h,time:settings.reduceMotion?0:elapsed,flags:game.state.flags,mission:{targetEntityId:surfaceTarget}});if(surfaceTarget&&settings.guidance!=='expert'){const target=surface.entities.find(e=>e.id===surfaceTarget);if(target){const x=target.x-camera.cameraX,y=target.y-camera.cameraY;if(x<25||x>w-25||y<35||y>h-65){const px=Math.max(28,Math.min(w-28,x)),py=Math.max(38,Math.min(h-65,y)),angle=Math.atan2(y-h/2,x-w/2);ctx.save();ctx.translate(px,py);ctx.rotate(angle);ctx.fillStyle='#e6cd92';ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(-4,-4);ctx.lineTo(-4,4);ctx.fill();ctx.restore();ctx.font='7px monospace';ctx.textAlign=x>w/2?'right':'left';ctx.fillStyle='#e2d5a5';ctx.fillText(target.name,px+(x>w/2?-12:12),py+3);}}}}}else{if(!playing){const small=w<450;Object.assign(attract.system.bodies[0],{x:small?0:300,y:small?-240:-110,radius:small?160:170});}const data=playing?game:attract;renderer.draw(ctx,data,{width:w,height:h,time:elapsed,welcome:!playing,tracked,guidance:settings.guidance,motion:!settings.reduceMotion});if(playing)renderer.radar($('radarCanvas').getContext('2d'),game,tracked);}
 if(transitionFlash>0&&!settings.reduceMotion){transitionFlash=Math.max(0,transitionFlash-dt*.8);ctx.fillStyle=`rgba(178,225,218,${transitionFlash*.5})`;ctx.fillRect(0,0,w,h);for(let i=0;i<28;i++){ctx.strokeStyle=`rgba(191,229,218,${transitionFlash*.4})`;ctx.beginPath();ctx.moveTo(w/2,h/2);const a=i/28*Math.PI*2;ctx.lineTo(w/2+Math.cos(a)*w,h/2+Math.sin(a)*h);ctx.stroke();}}
 hudTimer+=dt;if(hudTimer>.16){if(playing)updateHUD();hudTimer=0;}requestAnimationFrame(frame);
}
